import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.Wk4ah3nE.js";const u=JSON.parse('{"title":"Contributing","description":"How to contribute to Proxmox VM Autoscale — development setup, testing, code style, and what makes a change easy to review.","frontmatter":{"title":"Contributing","description":"How to contribute to Proxmox VM Autoscale — development setup, testing, code style, and what makes a change easy to review.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/contributing.html"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/contributing.html"}],["meta",{"property":"og:title","content":"Contributing"}],["meta",{"property":"og:description","content":"How to contribute to Proxmox VM Autoscale — development setup, testing, code style, and what makes a change easy to review."}]]},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md","lastUpdated":null}'),n={name:"contributing.md"};function o(r,e,l,h,p,d){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Bug reports, fixes and features are all welcome. This page covers the practical parts; <a href="https://github.com/fabriziosalmi/proxmox-vm-autoscale/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a> in the repository is the canonical version.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>For anything beyond a bug fix, open an issue first. It is much less frustrating than finding out after the work is done that the direction was wrong.</p><p>Worth reading first: <a href="/proxmox-vm-autoscale/reference/architecture.html">architecture</a> for how the pieces fit, and <a href="/proxmox-vm-autoscale/reference/limitations.html">known limitations</a> for what is already known — several of those are good first contributions.</p><h2 id="development-setup" tabindex="-1">Development setup <a class="header-anchor" href="#development-setup" aria-label="Permalink to &quot;Development setup&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/YOUR_USERNAME/proxmox-vm-autoscale.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proxmox-vm-autoscale</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span></span></code></pre></div><p>You do not need a Proxmox host to work on most of this — the test suite mocks SSH throughout.</p><h2 id="running-the-tests" tabindex="-1">Running the tests <a class="header-anchor" href="#running-the-tests" aria-label="Permalink to &quot;Running the tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                    # everything</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/test_vm_hotplug.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # one file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cooldown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        # by name</span></span></code></pre></div><p>114 tests, under a second. CI runs them on Python 3.9 through 3.12, plus <code>shellcheck -S warning install.sh</code>.</p><h2 id="what-a-good-change-looks-like" tabindex="-1">What a good change looks like <a class="header-anchor" href="#what-a-good-change-looks-like" aria-label="Permalink to &quot;What a good change looks like&quot;">​</a></h2><p><strong>Tests that fail before the fix.</strong> The most useful thing you can include is a test that demonstrates the bug against <code>main</code>. It proves the problem is real and stops it coming back.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stash</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                    # set your fix aside</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/test_your_new_test.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # should fail</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/test_your_new_test.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # should pass</span></span></code></pre></div><p><strong>No unrelated changes.</strong> Reformatting a file you happened to open makes the actual change impossible to see.</p><p><strong>Documentation updated in the same PR</strong> when behaviour changes. The docs live in <code>docs/</code>; every page has an &quot;Edit this page&quot; link.</p><p><strong>A changelog entry</strong> under <code>## [Unreleased]</code> in <code>CHANGELOG.md</code> for anything user-visible.</p><h2 id="code-style" tabindex="-1">Code style <a class="header-anchor" href="#code-style" aria-label="Permalink to &quot;Code style&quot;">​</a></h2><p>Match what is already there. Specifically:</p><ul><li>4-space indentation, no tabs</li><li><code>snake_case</code> for functions and variables, <code>PascalCase</code> for classes</li><li>Docstrings on public methods, saying what the method does and what it returns</li><li>Type hints where the surrounding code uses them — <code>autoscale.py</code> and <code>billing_tracker.py</code> are annotated, <code>vm_manager.py</code> and <code>ssh_utils.py</code> largely are not; follow the file</li><li>Comments explain <em>why</em>, not <em>what</em>. The code already says what it does</li></ul><p>There is no linter in CI and no formatter config, so consistency is by hand.</p><h2 id="commit-messages" tabindex="-1">Commit messages <a class="header-anchor" href="#commit-messages" aria-label="Permalink to &quot;Commit messages&quot;">​</a></h2><p>Conventional-commit prefixes, imperative mood:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fix: enforce scaling_limits from config.yaml</span></span>
<span class="line"><span>feat: add per-VM threshold overrides</span></span>
<span class="line"><span>docs: document the balloon fallback path</span></span>
<span class="line"><span>test: cover NUMA detection with no numa line</span></span>
<span class="line"><span>chore: bump paramiko</span></span></code></pre></div><p>Explain the reasoning in the body when a one-line subject cannot carry it. A reader six months from now needs to know why, not just what.</p><h2 id="pull-requests" tabindex="-1">Pull requests <a class="header-anchor" href="#pull-requests" aria-label="Permalink to &quot;Pull requests&quot;">​</a></h2><ol><li>Branch from <code>main</code> — <code>fix/...</code> or <code>feat/...</code></li><li>Make the change, add tests, update docs</li><li><code>pytest -q</code> and <code>shellcheck -S warning install.sh</code> clean</li><li>Push and open the PR</li></ol><p>In the description: what changed, why, how you verified it, and any behaviour change existing installations will notice.</p><h2 id="areas-that-need-work" tabindex="-1">Areas that need work <a class="header-anchor" href="#areas-that-need-work" aria-label="Permalink to &quot;Areas that need work&quot;">​</a></h2><p>Pulled from <a href="/proxmox-vm-autoscale/reference/limitations.html">known limitations</a>, roughly by value:</p><table tabindex="0"><thead><tr><th>Area</th><th>What is needed</th></tr></thead><tbody><tr><td><strong>Metric parsing</strong></td><td>Replace the <code>pvesh</code> table scrape with <code>--output-format json</code>. Removes a whole class of silent failure</td></tr><tr><td><strong>Non-RSA SSH keys</strong></td><td>Load Ed25519 and ECDSA keys, not just RSA</td></tr><tr><td><strong>Billing reporting</strong></td><td>Wire <code>generate_period_report</code> into the loop on a period boundary; make the cost calculation honour uptime</td></tr><tr><td><strong>Per-VM thresholds</strong></td><td>The config already shows them; the code does not read them</td></tr><tr><td><strong>Host key verification</strong></td><td>Replace the auto-add policy with something verifiable</td></tr><tr><td><strong>Dry-run mode</strong></td><td>Log what would happen without issuing commands</td></tr><tr><td><strong>Metrics endpoint</strong></td><td>Prometheus exposition for cycle count, decisions, failures</td></tr></tbody></table><h2 id="reporting-bugs" tabindex="-1">Reporting bugs <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;Reporting bugs&quot;">​</a></h2><p><a href="https://github.com/fabriziosalmi/proxmox-vm-autoscale/issues/new/choose" target="_blank" rel="noreferrer">Open an issue</a> with:</p><ul><li>What you expected and what happened</li><li>Steps to reproduce</li><li>Proxmox version (<code>pveversion</code>), Python version, OS</li><li>Relevant log excerpts</li><li>Your config <strong>with every credential removed</strong></li></ul><p>Security issues go through <a href="/proxmox-vm-autoscale/security/disclosure.html">responsible disclosure</a> instead — never a public issue.</p><h2 id="code-of-conduct" tabindex="-1">Code of conduct <a class="header-anchor" href="#code-of-conduct" aria-label="Permalink to &quot;Code of conduct&quot;">​</a></h2><p>Participation is covered by the <a href="https://github.com/fabriziosalmi/proxmox-vm-autoscale/blob/main/CODE_OF_CONDUCT.md" target="_blank" rel="noreferrer">Code of Conduct</a>.</p><h2 id="licence" tabindex="-1">Licence <a class="header-anchor" href="#licence" aria-label="Permalink to &quot;Licence&quot;">​</a></h2><p>Contributions are licensed under the <a href="https://github.com/fabriziosalmi/proxmox-vm-autoscale/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT Licence</a>, same as the project.</p>`,39)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
